private void ShowUserNameFormatError()
{
    ShowLoginError("Tên đăng nhập không đúng định dạng.");
}

private int GetLoginFailCount()
{
    if (Session[SESSION_LOGIN_FAIL_COUNT] == null)
        return 0;

    return Convert.ToInt32(Session[SESSION_LOGIN_FAIL_COUNT]);
}

private void SetLoginFailCount(int count)
{
    Session[SESSION_LOGIN_FAIL_COUNT] = count;
}

private void IncrementLoginFailCount()
{
    SetLoginFailCount(GetLoginFailCount() + 1);
}

private void ResetLoginFailCount()
{
    Session[SESSION_LOGIN_FAIL_COUNT] = null;
    txtCaptchaCode.Text = "";
}

private bool IsCaptchaRequired()
{
    return GetLoginFailCount() >= CAPTCHA_AFTER_FAIL_COUNT;
}

private void UpdateCaptchaVisibility()
{
    if (divCaptchaWrap != null)
        divCaptchaWrap.Visible = IsCaptchaRequired();
}

private void RefreshCaptchaIfRequired()
{
    if (!IsCaptchaRequired())
        return;

    txtCaptchaCode.Text = "";
    ScriptManager.RegisterStartupScript(this, this.GetType(), "_RefreshLoginCaptcha",
        "RefreshLoginCaptcha();", true);
}

private bool ValidateCaptcha()
{
    if (!IsCaptchaRequired())
        return true;

    if (txtCaptchaCode.Text.Trim() == "")
    {
        ShowLoginError("Vui lòng nhập mã bảo mật.");
        RefreshCaptchaIfRequired();
        return false;
    }

    if (Session[CaptChaImage.SESSION_CAPTCHA] == null ||
        Session[CaptChaImage.SESSION_CAPTCHA].ToString() != txtCaptchaCode.Text.Trim())
    {
        ShowLoginError("Mã bảo mật không đúng.");
        RefreshCaptchaIfRequired();
        return false;
    }

    return true;
}

protected void btnLogin_Click(object sender, EventArgs e)
{
    ClearLoginError();
    UpdateCaptchaVisibility();

    if (txtUserName.Text.Trim() == "" || txtPassword.Text == "")
    {
        ShowLoginError("Vui lòng nhập đầy đủ tên đăng nhập và mật khẩu.");
        return;
    }

    string strLoginName = txtUserName.Text.Trim();
    if (!IsValidLoginName(strLoginName))
    {
        ShowUserNameFormatError();
        return;
    }

    if (!ValidateCaptcha())
        return;

    DoLogin(strLoginName, txtPassword.Text);
}

